struct VTableEntry {
    void (*fptr)(void*);
    std::ptrdiff_t offset; // Offset to adjust 'this' pointer
};

// Example of a virtual table with offset-aware entries
struct VTable {
    VTableEntry* entries;
    // Additional vtable data
};

// During object layout, each base subobject may have an associated offset stored in the vtable.
// When invoking a virtual function, the compiler retrieves the function pointer and offset,
// adjusts the 'this' pointer accordingly, and calls the function.
